contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 mintAmount, uint256 transferAmount) public {
        require(from != address(0), "from zero");
        require(to != address(0), "to zero");
        require(from != to, "same account");

        // Give `from` tokens so the transfer can succeed.
        // mintSynth is onlyPool, so instead use transferFrom from this contract's balance? No token of C can be minted by anyone here.
        // However, the test's constructor contract deployed c and is the only account that can mint via Pool, which is not available.
        // We instead rely on `from` being this contract? But we can't mint to it.
        // Observed workaround: use the amount sent to `from` via the public `transfer` from the deployer/current msg.sender? No initial balance.
        // Wait: C._mint is internal; we cannot mint. So a transfer with nonzero amount from a zero-balance account will revert.
        // Better: test the failure condition: transfer of amount greater than balance must revert.
        // But we need general rule that always holds. Use: transfer of more than balance reverts, or if balance sufficient then balances change consistently.
        // But we can't set up sufficient balance. However, we can test totalSupply invariance and allowance behavior without needing tokens.
        // Let's test approve and transferFrom allowance reduction rule.
        // Actually, transferFrom with amount > balance reverts. We can test that if it doesn't revert, sender balance decreased and recipient increased.
        // But without initial balance, transferFrom from any sender with amount > 0 will revert.
        // So use transferAmount = 0: transfer of 0 succeeds and doesn't change anything.
        // That's too trivial. Choose a meaningful rule that doesn't require setup:
        // "approve(spender, amount) sets allowance to amount unless current allowance is max, in which case it stays max."
        // But _approve in C sets unconditionally (no max check). So allowance always equals amount after approve.
        // Rule: after c.approve(spender, amt), c.allowance(address(this), spender) == amt.
        // That's a clean general rule about state change. It always holds for any spender and amt.
        // However, the task wants a rule about transfer/balance etc. Let's do:
        // transferFrom: if it does not revert, then allowance is reduced by amount (unless it was max, then unchanged).
        // This requires setting a nonzero allowance and balance? allowance can be set by approve. balance still zero.
        // transferFrom with amount 0: succeeds regardless of balance; allowance reduces by 0 (no change) unless max logic? In C, if allowance < max, it requires allowance >= amount (0>=0 true) then sets allowance = currentAllowance - amount = same. So no change. That's not interesting.
        // We can test that transferFrom of amount > 0 from account with zero balance reverts. That's a revert rule. Good general rule: for any sender with balance 0, transferFrom with amount > 0 reverts. We can set allowance first via approve.
        // But we can't easily prove sender balance is 0 (it's private mapping, but balanceOf is public). So we can use c.balanceOf(from) == 0 as precondition.
        // Rule: if from has zero balance, then transferFrom(from, to, amount) with amount > 0 must revert.
        // This holds because _transfer requires senderBalance >= amount.
        // That's a solid general rule. But need to ensure allowance doesn't cause a different revert? transferFrom calls _transfer first, so it reverts with "!balance".
        // That's fine. Let's do that.

        uint256 fromBalance = c.balanceOf(from);
        if (fromBalance == 0 && transferAmount > 0) {
            // set allowance from this to from? No, we need msg.sender to be this contract calling transferFrom(from, to, amount).
            // But transferFrom is called by this contract as spender, so we need allowance[from][address(this)] >= amount.
            // We can set it by calling c.approve? No, approve sets allowance[msg.sender][spender], so only from can approve. We as this contract can't set allowance from 'from'.
            // So transferFrom will revert due to insufficient allowance before balance check? In C, transferFrom: _transfer(sender, recipient, amount) first, so balance check happens before allowance check. Good: it reverts with "!balance" regardless of allowance.
            // So we don't need allowance.
        }
        // We cannot force a revert with amount > 0 if fromBalance == 0? Actually if balance is 0 and amount > 0, _transfer reverts.
        // So try transferFrom and check it reverts.
        bool reverted;
        try c.transferFrom(from, to, transferAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: if from has zero balance and transferAmount > 0, then transferFrom must revert.
        // But what if fromBalance > 0? Then we can't assert revert. So rule: (fromBalance == 0 && transferAmount > 0) => reverted.
        // However, we need to ensure the condition is actually reachable: we need some account with zero balance. Any address not this contract or c itself likely has zero. But we can pick from = address(0)? Not allowed. Use a parameter address that is not this or c.
        // But we cannot control fromBalance; it could be nonzero if from == address(c) or this contract. So add require that from is not this contract and not address(c), and fromBalance == 0? But require on c state after call? Actually require before is allowed if condition is on parameters? We can require from != address(this) && from != address(c) && c.balanceOf(from) == 0. But that's a precondition on c's state, which is allowed as long as we don't require it before the call that creates it? The instructions say: "Never require() a condition on c's state before the call that creates it." Here the state (balance) pre-exists; it's not created by a call in this function. So it's fine to require c.balanceOf(from) == 0. But that makes the rule conditional. The assert should be: if precondition holds then reverted is true. But we can just include the precondition in the assert: (c.balanceOf(from) == 0 && transferAmount > 0) => reverted.
        // However, if fromBalance != 0, the rule is vacuously true. So we can assert: fromBalance != 0 || transferAmount == 0 || reverted. That's not a good general rule because it's almost always true.
        // Let's instead assert: if fromBalance == 0 and transferAmount > 0 then reverted. But we need to ensure the call actually happened. We have the revert boolean.
        // So assert( !(c.balanceOf(from) == 0 && transferAmount > 0) || reverted );
        // That's a tautology? No, it's the statement of the rule. It can be false if a faulty version allowed zero-balance transfer.
        // Good.
        assert(!(fromBalance == 0 && transferAmount > 0) || reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 transferAmount) public {
        require(from != address(0), "from zero");
        require(to != address(0), "to zero");
        require(from != address(this), "this");
        require(from != address(c), "c");

        uint256 balanceBefore = c.balanceOf(from);
        uint256 supplyBefore = c.totalSupply();
        require(balanceBefore == 0, "balance not zero");

        bool reverted;
        try c.transferFrom(from, to, transferAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (transferAmount > 0) {
            assert(reverted);
        } else {
            assert(!reverted);
        }
        assert(c.balanceOf(from) == balanceBefore);
        assert(c.totalSupply() == supplyBefore);
    }

    receive() external payable {}
}

