contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address pool,
        uint256 synthAmount,
        uint256 lpBalanceBefore,
        uint256 lpDebtBefore
    ) public {
        require(pool != address(0));
        require(lpDebtBefore > 0);

        // Burn the synthetic amount from this contract, leaving it in c's balance
        // for the subsequent burnSynth call.
        try c.burn(synthAmount) {
            // If burn succeeded, c's balance now includes synthAmount (assuming it was minted/available).
        } catch {
            // If burn fails, burnSynth may still succeed if c's balance already suffices,
            // but the property we check later only concerns successful burnSynth calls.
        }

        uint256 cBalance = c.balanceOf(address(this));
        require(cBalance > 0);

        // After burning, the synth held by c should equal the amount passed to burnSynth.
        // Our property compares burnSynth's effect against the same LP balance and debt
        // that are stored before the call.

        (bool burnSynthSucceeded, ) = address(c).call(
            abi.encodeWithSignature("burnSynth()")
        );

        if (burnSynthSucceeded) {
            uint256 lpBalanceAfter = c.getmapAddress_LPBalance(pool);
            uint256 lpDebtAfter = c.getmapAddress_LPDebt(pool);

            // No underflow in the computation of _amountUnits:
            // _amountUnits = (cBalance * lpBalanceBefore) / lpDebtBefore.
            // burning cBalance requires cBalance <= lpDebtBefore:
            if (lpBalanceBefore <= lpDebtBefore) {
                assert(lpBalanceAfter <= lpBalanceBefore && lpDebtAfter == lpDebtBefore - cBalance);
            }
        }
    }

    receive() external payable {}
}

