        require(member != address(0), "member zero");
        require(burnCaller != address(0), "caller zero");

        // Read before-state so the rule can compare against later values.
        uint beforeTotalSupply = c.totalSupply();
        uint beforeBurnerBalance = c.balanceOf(address(this));
        uint beforePoolLPBalance = c.getmapAddress_LPBalance(member);
        uint beforePoolLPDebt = c.getmapAddress_LPDebt(member);

