        uint afterPoolLPBalance = c.getmapAddress_LPBalance(member);
        uint afterPoolLPDebt = c.getmapAddress_LPDebt(member);

        // General rule: burnSynth is a proportionally-decreasing operation on the
        // sender's LP accounting, and it never increases total supply, the caller's
        // token balance, or the stored LP balance/debt of any pool.
        assert(
            reverted ||
            (
                afterTotalSupply <= beforeTotalSupply &&
                afterBurnerBalance <= beforeBurnerBalance &&
                afterPoolLPBalance <= beforePoolLPBalance &&
                afterPoolLPDebt <= beforePoolLPDebt
            )
        );
    }

    receive() external payable {}
}

