contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        // If the caller has neither tokens nor allowance to mutate state, any effect rule is vacuous,
        // so give the caller a non-zero balance without assuming anything about private state.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        if (balBefore < amount) {
            c.burn(balBefore);
        }

        balBefore = c.balanceOf(address(this));
        supplyBefore = c.totalSupply();

        // The deciding call: transfer exactly `amount` from the test contract to `to`.
        // Because balances are conserved by _transfer, this must succeed iff amount <= balBefore.
        uint256 amountToSend = amount > balBefore ? balBefore : amount;
        uint256 recvBefore = c.balanceOf(to);
        c.transfer(to, amountToSend);
        uint256 recvAfter = c.balanceOf(to);
        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        assert(balAfter == balBefore - amountToSend && recvAfter == recvBefore + amountToSend && supplyAfter == supplyBefore);
    }

    receive() external payable {}
}

