    }

    function run(address owner, address spender, uint256 approveAmount, uint256 burnAmount) public {
        // Avoid zero-address reverts from approve/burn.
        require(owner != address(0));
        require(spender != address(0));

        // Impersonate the owner so that c.approve sets the owner's allowance.
        (bool ok1, ) = address(c).call(
            abi.encodeWithSignature("approve(address,uint256)", spender, approveAmount)
        );
        require(ok1);

        // Read the allowance that was actually recorded through the public getter.
        uint256 allowanceBefore = c.allowance(owner, spender);

        // The actual state-changing call must be a top-level statement.
        bool reverted;
        try c.burnFrom(owner, burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 allowanceAfter = c.allowance(owner, spender);

        // General rule: burning more than the owner's allowance must revert, and when it
        // reverts the allowance recorded in c must be unchanged.
        assert(!(burnAmount > allowanceBefore) || (reverted && allowanceAfter == allowanceBefore));
    }

    receive() external payable {}
}

