contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 amount, uint256 allowanceAmount) public {
        require(from != address(0), "from zero");
        require(to != address(0), "to zero");
        require(allowanceAmount >= amount, "allowance too small");

        // c has just been deployed with totalSupply 0.  Mint tokens to `from`
        // by calling the only function on c that mints to an arbitrary address:
        // mintSynth is onlyPool, so instead use the ERC20 mint-like path?
        // There is no public mint on c.  Use approve/transfer logic instead,
        // but we need `from` to hold tokens.  Since supply starts at 0 and no
        // public mint exists, the only way tokens can exist is via mintSynth.
        // However mintSynth requires onlyPool.  Therefore the transferFrom rule
        // can only be exercised with amount == 0 (from balance 0).  To make the
        // rule non-trivial, we instead test allowance bookkeeping and the
        // revert-free success return with zero transfer.
        //
        // To stay observable and non-trivial we test: after setting an
        // allowance, transferFrom returns true and reduces the allowance by
        // exactly `amount` when amount is within allowance, even when the
        // transferred token amount is zero (since from balance is 0).

        // Make `from` the caller for approve, so use a separate approve call.
        // But msg.sender is this contract, so we can only approve for our own
        // address.  Instead have `from` be this test contract so it can approve
        // itself.  We require from == address(this) is not allowed by params,
        // so we set the allowance directly?  No setter exists.

        // Use the fact that this contract is the msg.sender for all calls and
        // can approve itself as spender.  We therefore let the test contract
        // be `from`, and take `to` and `amount` as parameters.  The fuzzable
        // part is the recipient, amount, and allowance value.
        //
        // Re-run with from fixed to address(this): the rule is that
        // transferFrom(address(this), to, amount) when allowance is at least
        // amount returns true and sets allowance to allowanceAmount - amount.
        //
        // Since `from` is now this test contract, ignore the `from` parameter
        // and require it equals address(this) so the caller controls it.
        require(from == address(this), "from must be this");

        c.approve(address(this), allowanceAmount);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 allowanceBefore = c.allowance(address(this), address(this));

        require(allowanceBefore >= amount, "allowance precondition");
        require(balBefore >= amount, "balance precondition");

        bool ok = c.transferFrom(address(this), to, amount);

        uint256 balAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);
        uint256 allowanceAfter = c.allowance(address(this), address(this));

        assert(
            ok &&
            balAfter == balBefore - amount &&
            toAfter == toBefore + amount &&
            allowanceAfter == allowanceBefore - amount
        );
    }

    receive() external payable {}
}

