contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address member, uint256 amount, address pool) public payable {
        uint256 initialMemberSynth = c.balanceOf(member);
        uint256 initialThisSynth = c.balanceOf(address(this));

        (bool minted, bytes memory mintRet) = address(c).call(
            abi.encodeWithSignature("mintSynth(address,uint256)", member, amount)
        );

        uint256 afterMintMemberSynth = c.balanceOf(member);
        uint256 afterMintThisSynth = c.balanceOf(address(this));

        bool mintedSucceeded = minted;
        uint256 returnedAmount = 0;
        if (mintedSucceeded && mintRet.length >= 32) {
            returnedAmount = abi.decode(mintRet, (uint256));
        }

        uint256 poolBalanceBeforeBurn = c.getmapAddress_LPBalance(pool);
        uint256 poolDebtBeforeBurn = c.getmapAddress_LPDebt(pool);

        (bool burned, ) = address(c).call(
            abi.encodeWithSignature("burnSynth()")
        );

        uint256 poolBalanceAfterBurn = c.getmapAddress_LPBalance(pool);
        uint256 poolDebtAfterBurn = c.getmapAddress_LPDebt(pool);
        uint256 afterBurnThisSynth = c.balanceOf(address(this));

        assert(
            (mintedSucceeded && returnedAmount == amount) ||
            (!mintedSucceeded) ||
            (
                mintedSucceeded &&
                burned &&
                afterBurnThisSynth == 0 &&
                poolBalanceAfterBurn <= poolBalanceBeforeBurn &&
                poolDebtAfterBurn <= poolDebtBeforeBurn &&
                afterMintMemberSynth >= initialMemberSynth &&
                afterMintThisSynth >= initialThisSynth
            )
        );
    }

    receive() external payable {}
}

