            reverted = true;
        }

        if (!reverted) {
            // General rule: mintSynth credits exactly `amount` synthetic tokens
            // to `member` and returns that same amount.
            uint256 balanceAfter = c.balanceOf(member);
            assert(returnedAmount == amount);
            assert(balanceAfter == balanceBefore + amount);
        } else {
            // Reversion must not leave any state change in the member's balance.
            uint256 balanceAfter = c.balanceOf(member);
            assert(balanceAfter == balanceBefore);
        }
    }
}

