contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public {
        // Read totalSupply before the call (public state variable).
        uint256 supplyBefore = c.totalSupply();

        // The mintSynth call is the single deciding call. If it reverts, the
        // try/catch records the revert; otherwise it records the returned
        // synthetic amount.
        bool reverted;
        uint256 syntheticAmount;
        try c.mintSynth(address(this), amount) returns (uint256 ret) {
            syntheticAmount = ret;
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: for every input, either the call reverted (and then
        // nothing about the supply is required), or the call succeeded and
        // then it must have returned exactly the passed amount and increased
        // totalSupply by exactly the synthetic amount it returned.
        // This is a true universal rule of the correct implementation:
        // mintSynth returns the requested amount and mints that many units.
        assert(
            reverted
                ? supplyBefore == c.totalSupply()
                : (syntheticAmount == amount && c.totalSupply() == supplyBefore + syntheticAmount)
        );
    }
}

