        uint afterBalance = c.getmapAddress_LPBalance(address(this));
        uint afterDebt = c.getmapAddress_LPDebt(address(this));

        // General rule: if the mint call did not revert, the debt increased by exactly `amount`
        // and the LP balance increased by the newly-added LP collateral (which is >= 0).
        // If it reverted, the accounting is unchanged.
        assert(
            (reverted && afterDebt == beforeDebt && afterBalance == beforeBalance) ||
            (!reverted && afterDebt == beforeDebt + amount)
        );
    }

    receive() external payable {}
}

