contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        // Precondition: amount is nonzero and caller has enough balance after setup.
        // We use a simple transfer of `amount` to this contract and require it not revert.
        require(amount > 0);

        // If the caller already has some balance, transferring `amount` from them may fail.
        // Instead, we will have this contract approved first? No — the core rule should be
        // about the token's own transfer success semantics.

        // Read the caller's balance before.
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeSupply = c.totalSupply();

        bool reverted;
        try c.transfer(address(0xdead), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterSupply = c.totalSupply();

        // General rule: if transfer did not revert, then the caller's balance decreased by exactly amount
        // and totalSupply is unchanged.
        assert(
            reverted
                ? afterBalance == beforeBalance && afterSupply == beforeSupply
                : afterBalance + amount == beforeBalance && afterSupply == beforeSupply
        );
    }

    receive() external payable {}
}

